import{_ as e,o as l,c as d,a2 as a}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"인스턴트 답변 및 키워드 확장 기능","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/user-guide/instant-answers.md","filePath":"ko-KR/user-guide/instant-answers.md","lastUpdated":1788190459000}'),o={name:"ko-KR/user-guide/instant-answers.md"};function s(n,t,i,r,c,g){return l(),d("div",null,[...t[0]||(t[0]=[a(`<h1 id="인스턴트-답변-및-키워드-확장-기능" tabindex="-1">인스턴트 답변 및 키워드 확장 기능 <a class="header-anchor" href="#인스턴트-답변-및-키워드-확장-기능" aria-label="Permalink to &quot;인스턴트 답변 및 키워드 확장 기능&quot;">​</a></h1><p>Lertaro는 로컬 파일 검색 외에도 강력한 즉시 계산, 시스템 도구 및 키워드 기반 확장 플러그인을 제공합니다. 파일 검색 결과를 기다릴 필요 없이 해당 명령어를 입력하여 즉각적인 결과를 얻을 수 있습니다.</p><h2 id="_1-상시-활성화된-인스턴트-기능" tabindex="-1">1. 상시 활성화된 인스턴트 기능 <a class="header-anchor" href="#_1-상시-활성화된-인스턴트-기능" aria-label="Permalink to &quot;1. 상시 활성화된 인스턴트 기능&quot;">​</a></h2><p>키워드 접두사 없이도 입력된 텍스트가 특정 패턴과 일치하면 즉시 실행됩니다.</p><h3 id="계산기-및-진법-변환" tabindex="-1">계산기 및 진법 변환 <a class="header-anchor" href="#계산기-및-진법-변환" aria-label="Permalink to &quot;계산기 및 진법 변환&quot;">​</a></h3><p>검색창에 수학 수식을 직접 입력하면 첫 번째 줄에 결과가 실시간으로 표시됩니다. <code>Enter</code>를 누르면 계산 결과가 클립보드에 복사됩니다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>12 * (4 + 3)</span></span>
<span class="line"><span>100 * (1 - 0.15)</span></span></code></pre></div><p>진법 변환도 기본 지원합니다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>255 to hex</span></span>
<span class="line"><span>0xFF to dec</span></span>
<span class="line"><span>101010 to bin</span></span></code></pre></div><h3 id="환경-변수-확장-및-검색" tabindex="-1">환경 변수 확장 및 검색 <a class="header-anchor" href="#환경-변수-확장-및-검색" aria-label="Permalink to &quot;환경 변수 확장 및 검색&quot;">​</a></h3><ul><li><strong>변수 값 확인</strong>: <code>%NAME%</code>(예: <code>%PATH%</code>, <code>%APPDATA%</code>)을 입력하여 실제 경로 값을 확인합니다. <code>PATH</code>처럼 여러 경로가 포함된 변수는 줄바꿈 목록으로 깔끔하게 자동 전개됩니다.</li><li><strong>환경 변수 퍼지 검색</strong>: <code>%</code> 뒤에 키워드를 입력(예: <code>%temp</code>)하면 해당 단어가 포함된 시스템/사용자 환경 변수를 검색합니다.</li></ul><h3 id="명령어-즉시-실행" tabindex="-1">명령어 즉시 실행 <a class="header-anchor" href="#명령어-즉시-실행" aria-label="Permalink to &quot;명령어 즉시 실행&quot;">​</a></h3><p>터미널을 따로 열지 않고 검색창에서 직접 명령을 실행할 수 있습니다.</p><ul><li><code>#&lt;명령어&gt;</code>: 명령 프롬프트를 열고 <strong>관리자 권한으로 실행</strong>합니다(예: <code>#sfc /scannow</code> 또는 <code>#net start Lertaro.Service</code>).</li><li><code>$&lt;명령어&gt;</code>: 명령 프롬프트를 열고 <strong>일반 사용자 권한으로 실행</strong>합니다(예: <code>$ping 1.1.1.1</code> 또는 <code>$ipconfig /all</code>).</li></ul><h3 id="웹-url-바로-열기" tabindex="-1">웹 URL 바로 열기 <a class="header-anchor" href="#웹-url-바로-열기" aria-label="Permalink to &quot;웹 URL 바로 열기&quot;">​</a></h3><p><code>http://</code> 또는 <code>https://</code>로 시작하는 URL을 입력하거나 붙여넣고 <code>Enter</code>를 누르면 기본 브라우저에서 즉시 열립니다. 검색 결과가 없고 입력이 프로토콜 없는 도메인으로 시작하면 빠른 검색 창이 자동으로 <code>https://</code>를 채우고 커서를 끝으로 이동합니다. 이미 프로토콜이 포함된 입력은 변경하지 않습니다.</p><h3 id="빠른-검색-창의-클립보드-텍스트-가져오기" tabindex="-1">빠른 검색 창의 클립보드 텍스트 가져오기 <a class="header-anchor" href="#빠른-검색-창의-클립보드-텍스트-가져오기" aria-label="Permalink to &quot;빠른 검색 창의 클립보드 텍스트 가져오기&quot;">​</a></h3><p>미리 입력된 내용 없이 빠른 검색 창을 호출하면 클립보드가 비어 있지 않고 같은 창에서 직전에 가져온 값과 다를 때 텍스트를 자동으로 입력하고 전체 선택합니다. 같은 값은 반복해서 가져오지 않으며 URI 또는 전체 검색 창에서 돌아올 때의 미리 입력된 내용도 덮어쓰지 않습니다.</p><h2 id="_2-키워드-실행-기능-내장-플러그인" tabindex="-1">2. 키워드 실행 기능 (내장 플러그인) <a class="header-anchor" href="#_2-키워드-실행-기능-내장-플러그인" aria-label="Permalink to &quot;2. 키워드 실행 기능 (내장 플러그인)&quot;">​</a></h2><p>짧은 <strong>트리거 키워드 + 공백</strong> 뒤에 쿼리를 입력하여 전용 플러그인 기능을 호출할 수 있습니다. 모든 키워드는 <a href="./settings/plugins.html"><strong>설정 → 플러그인</strong></a>에서 변경할 수 있습니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">기본 키워드</th><th style="text-align:left;">플러그인 이름</th><th style="text-align:left;">기능 설명 및 활용</th><th style="text-align:left;">사용 예시</th></tr></thead><tbody><tr><td style="text-align:left;"><code>ps</code></td><td style="text-align:left;"><strong>프로세스 관리</strong></td><td style="text-align:left;">실행 중인 프로세스를 이름, PID, 창 제목으로 검색하고 Enter로 즉시 종료.</td><td style="text-align:left;"><code>ps chrome</code> 또는 <code>ps 1234</code></td></tr><tr><td style="text-align:left;"><code>win</code></td><td style="text-align:left;"><strong>창 전환기</strong></td><td style="text-align:left;">열려 있는 앱 창을 검색하고 실시간 백그라운드 썸네일과 함께 즉시 전환.</td><td style="text-align:left;"><code>win code</code> 또는 <code>win 브라우저</code></td></tr><tr><td style="text-align:left;"><code>bm</code></td><td style="text-align:left;"><strong>브라우저 데이터</strong></td><td style="text-align:left;">Chrome, Edge, Firefox의 북마크 및 방문 기록 검색(북마크/기록 개별 토글 가능).</td><td style="text-align:left;"><code>bm github</code></td></tr><tr><td style="text-align:left;"><code>set</code></td><td style="text-align:left;"><strong>설정 검색</strong></td><td style="text-align:left;">Lertaro 내부의 모든 설정을 퍼지 검색. 선택 시 해당 설정 페이지로 즉시 이동 및 하이라이트.</td><td style="text-align:left;"><code>set 단축키</code> 또는 <code>set 퍼지</code></td></tr><tr><td style="text-align:left;"><code>flow</code></td><td style="text-align:left;"><strong>Flow 플러그인 브리지</strong></td><td style="text-align:left;">로드된 Flow.Launcher 플러그인 및 트리거 목록을 확인하고 Flow 생태계 활용.</td><td style="text-align:left;"><code>flow</code></td></tr><tr><td style="text-align:left;"><code>cs</code></td><td style="text-align:left;"><strong>콘텐츠 검색</strong></td><td style="text-align:left;">인덱싱된 로컬 문서 본문을 검색하고 일부 내용과 함께 일치하는 파일을 표시합니다.</td><td style="text-align:left;"><code>cs 프로젝트 계획</code></td></tr></tbody></table><h2 id="_3-웹-검색-엔진-바로가기" tabindex="-1">3. 웹 검색 엔진 바로가기 <a class="header-anchor" href="#_3-웹-검색-엔진-바로가기" aria-label="Permalink to &quot;3. 웹 검색 엔진 바로가기&quot;">​</a></h2><p>웹 검색 플러그인에는 주요 검색 엔진이 내장되어 있어 접두사 뒤에 검색어를 입력하면 브라우저에서 바로 검색할 수 있습니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">단축어</th><th style="text-align:left;">검색 엔진</th><th style="text-align:left;">예시</th><th style="text-align:left;">설명</th></tr></thead><tbody><tr><td style="text-align:left;"><code>bd</code></td><td style="text-align:left;">바이두 (Baidu)</td><td style="text-align:left;"><code>bd 딥러닝</code></td><td style="text-align:left;">Baidu에서 검색</td></tr><tr><td style="text-align:left;"><code>g</code></td><td style="text-align:left;">구글 (Google)</td><td style="text-align:left;"><code>g lertaro github</code></td><td style="text-align:left;">Google에서 검색</td></tr><tr><td style="text-align:left;"><code>bing</code></td><td style="text-align:left;">빙 (Bing)</td><td style="text-align:left;"><code>bing 마이크로소프트 문서</code></td><td style="text-align:left;">Bing에서 검색</td></tr><tr><td style="text-align:left;"><code>gh</code></td><td style="text-align:left;">깃허브 (GitHub)</td><td style="text-align:left;"><code>gh Lertaro</code></td><td style="text-align:left;">GitHub 저장소에서 바로 검색</td></tr><tr><td style="text-align:left;"><code>wiki</code></td><td style="text-align:left;">위키백과 (Wikipedia)</td><td style="text-align:left;"><code>wiki 양자역학</code></td><td style="text-align:left;">위키백과 항목 검색</td></tr><tr><td style="text-align:left;"><code>yt</code></td><td style="text-align:left;">유튜브 (YouTube)</td><td style="text-align:left;"><code>yt lofi hip hop</code></td><td style="text-align:left;">YouTube 동영상 검색</td></tr></tbody></table><p><strong>설정 → 플러그인 → 웹 검색 → 설정</strong>에서 새 검색 엔진과 커스텀 URL 템플릿을 추가/편집/삭제할 수 있습니다.</p><h2 id="_4-즉시-번역" tabindex="-1">4. 즉시 번역 <a class="header-anchor" href="#_4-즉시-번역" aria-label="Permalink to &quot;4. 즉시 번역&quot;">​</a></h2><p>기본 트리거 <code>tr</code> 뒤에 번역할 텍스트를 입력하면 Lertaro UI 언어로 자동 번역됩니다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tr Hello, how are you today?</span></span></code></pre></div><ul><li>타이핑 중 비동기적으로 번역 결과가 나타나며, <code>Enter</code>를 눌러 결과를 복사할 수 있습니다.</li><li><strong>설정 → 플러그인 → 번역 → 설정</strong>에서 트리거 단어를 변경할 수 있습니다.</li></ul><h2 id="_5-파일-필터" tabindex="-1">5. 파일 필터 <a class="header-anchor" href="#_5-파일-필터" aria-label="Permalink to &quot;5. 파일 필터&quot;">​</a></h2><p><strong>설정 → 플러그인 → 파일 필터 → 설정</strong>에서 특정 폴더 및 확장자에 국한된 전용 검색 범위를 만들 수 있습니다.</p><ul><li><strong>대상 폴더 지정</strong>: 특정 작업 디렉토리(예: <code>D:\\Engineering\\Drawings</code>)를 재귀적으로 스캔.</li><li><strong>확장자 규칙 지정</strong>: <code>*.dwg;*.dxf</code> 또는 <code>*.pdf;*.docx</code> 패턴 설정.</li><li><strong>트리거 키워드 할당</strong>: 전용 키워드(예: <code>cad</code>)를 할당하여 <code>cad 부품도</code>와 같이 특정 업무 파일만 격리 검색.</li></ul><h2 id="_6-커스텀-명령어" tabindex="-1">6. 커스텀 명령어 <a class="header-anchor" href="#_6-커스텀-명령어" aria-label="Permalink to &quot;6. 커스텀 명령어&quot;">​</a></h2><p><strong>설정 → 플러그인 → 커스텀 명령어 → 설정</strong>에서 복잡한 스크립트, CLI 도구, 외부 앱을 간단한 명령어로 래핑할 수 있습니다.</p><ul><li><strong>매개변수 플레이스홀더</strong>: 위치 플레이스홀더 <code>%s1</code>, <code>%s2</code>... 및 전체 입력 캡처 <code>%s</code> 지원.</li><li><strong>퀵 내비게이션 연동</strong>: &quot;퀵 내비게이션에 표시&quot;를 체크하면 <a href="./hotkeys.html#3-퀵-내비게이션-마우스-트리거"><strong>퀵 내비게이션</strong></a> 메뉴에 등록되며, <code>/</code>를 이용한 다단계 서브메뉴(예: <code>개발도구/서비스재시작</code>) 분류도 지원합니다.</li></ul>`,35)])])}const x=e(o,[["render",s]]);export{p as __pageData,x as default};
